_sage_const_200 = Integer(200); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_3 = Integer(3); _sage_const_0 = Integer(0); _sage_const_15 = Integer(15); _sage_const_80 = Integer(80); _sage_const_1en50 = RealNumber('1e-50'); _sage_const_70 = Integer(70); _sage_const_12 = Integer(12); _sage_const_1en100 = RealNumber('1e-100'); _sage_const_60 = Integer(60); _sage_const_1en200 = RealNumber('1e-200'); _sage_const_1024 = Integer(1024); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_16 = Integer(16); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_1en10 = RealNumber('1e-10')
import mpmath
mpmath.mp.dps = _sage_const_200

def psi_tail(j, m):
    """ψ_j(m) = ζ(j) - H_{m-1}^{(j)} = Σ_{ℓ≥m} 1/ℓ^j"""
    if j == _sage_const_2 :
        return mpmath.zeta(_sage_const_2 ) - sum(mpmath.mpf(_sage_const_1 )/mpmath.mpf(k)**_sage_const_2  for k in range(_sage_const_1 , int(m)))
    elif j == _sage_const_3 :
        return mpmath.zeta(_sage_const_3 ) - sum(mpmath.mpf(_sage_const_1 )/mpmath.mpf(k)**_sage_const_3  for k in range(_sage_const_1 , int(m)))

def compute_mop(n, n1, n2):
    """Compute monic MOP Q_n. Returns coefficients and Q_n(1)."""
    n = int(n); n1 = int(n1); n2 = int(n2)
    assert n1 + n2 == n and n1 >= _sage_const_0  and n2 >= _sage_const_0

    # Build n×n system: A * [c_0,...,c_{n-1}]^T = -b
    # where b[row] = M[row, n] (the column for c_n = 1)
    A = mpmath.matrix(n, n)
    b = mpmath.matrix(n, _sage_const_1 )

    # First n1 rows: ψ₁ conditions (ζ(2) moments)
    for row in range(n1):
        s = row + _sage_const_1
        for k in range(n):
            A[row, k] = psi_tail(_sage_const_2 , k + s)
        b[row, _sage_const_0 ] = -psi_tail(_sage_const_2 , n + s)

    # Next n2 rows: ψ₂ conditions (ζ(3) moments)
    for row in range(n2):
        s = row + _sage_const_1
        for k in range(n):
            A[n1 + row, k] = psi_tail(_sage_const_3 , k + s)
        b[n1 + row, _sage_const_0 ] = -psi_tail(_sage_const_3 , n + s)

    # Solve
    c_vec = mpmath.lu_solve(A, b)
    c = [c_vec[k, _sage_const_0 ] for k in range(n)] + [mpmath.mpf(_sage_const_1 )]

    Qn1 = sum(c)
    return c, Qn1

