max_n = _sage_const_15

for step_name, n1_fn in [
    ("balanced (⌈n/2⌉, ⌊n/2⌋)", lambda n: (n+_sage_const_1 )//_sage_const_2 ),
    ("ζ(2)-heavy (n-1, 1)", lambda n: n-_sage_const_1 ),
    ("ζ(3)-heavy (1, n-1)", lambda n: _sage_const_1 ),
    ("2:1 ratio (⌈2n/3⌉, ⌊n/3⌋)", lambda n: (_sage_const_2 *n+_sage_const_2 )//_sage_const_3 ),
]:
    print("\n--- Step-line: %s ---" % step_name)
    results = []
    for n in range(_sage_const_2 , max_n + _sage_const_1 ):
        n1 = int(n1_fn(n))
        n2 = int(n) - n1
        if n2 < _sage_const_1  or n1 < _sage_const_1 :
            continue
        try:
            c, Qn1 = compute_mop(n, n1, n2)
            results.append((n, Qn1, c))
            print("  n=%2d (n1=%d,n2=%d): Q_n(1) = %+.12e" % (n, n1, n2, float(Qn1)))
        except Exception as e:
            print("  n=%2d: FAILED: %s" % (n, str(e)[:_sage_const_80 ]))

    if len(results) >= _sage_const_2 :
        print("  Growth ratios Q_{n+1}(1)/Q_n(1):")
        for i in range(len(results) - _sage_const_1 ):
            na, va, _ = results[i]
            nb, vb, _ = results[i+_sage_const_1 ]
            if abs(va) > _sage_const_1en50  and nb == na + _sage_const_1 :
                r = float(vb / va)
                print("    n=%d→%d: ratio = %+.10f  (target: ~0.859)" % (na, nb, r))

