L = mpmath.zeta(_sage_const_2 ) + mpmath.zeta(_sage_const_3 )
print("L = ζ(2)+ζ(3) = %.30f" % float(L))

for step_name, n1_fn in [
    ("balanced", lambda n: (n+_sage_const_1 )//_sage_const_2 ),
    ("ζ(2)-heavy", lambda n: n-_sage_const_1 ),
]:
    print("\n--- %s ---" % step_name)
    errors = []
    for n in range(_sage_const_2 , min(max_n + _sage_const_1 , _sage_const_12 )):
        n1 = int(n1_fn(n))
        n2 = int(n) - n1
        if n2 < _sage_const_1  or n1 < _sage_const_1 :
            continue
        try:
            c, Qn1 = compute_mop(n, n1, n2)

            # p_n = Σ c_k (H_k^{(2)} + H_k^{(3)})
            p_n = mpmath.mpf(_sage_const_0 )
            for k in range(int(n)+_sage_const_1 ):
                Hk2 = sum(mpmath.mpf(_sage_const_1 )/mpmath.mpf(j)**_sage_const_2  for j in range(_sage_const_1 , int(k)+_sage_const_1 ))
                Hk3 = sum(mpmath.mpf(_sage_const_1 )/mpmath.mpf(j)**_sage_const_3  for j in range(_sage_const_1 , int(k)+_sage_const_1 ))
                p_n += c[k] * (Hk2 + Hk3)

            e_n = Qn1 * L - p_n
            errors.append((n, e_n, Qn1))
            rel = float(abs(e_n / Qn1)) if abs(Qn1) > _sage_const_1en100  else _sage_const_0
            print("  n=%2d: |e_n| = %.6e, |e_n/Q_n(1)| = %.6e" % (n, float(abs(e_n)), rel))
        except Exception as e:
            print("  n=%2d: %s" % (n, str(e)[:_sage_const_60 ]))

    if len(errors) >= _sage_const_2 :
        print("  Error decay ratios:")
        for i in range(len(errors) - _sage_const_1 ):
            na, ea, _ = errors[i]
            nb, eb, _ = errors[i+_sage_const_1 ]
            if abs(ea) > _sage_const_1en200  and nb == na + _sage_const_1 :
                r = float(abs(eb) / abs(ea))
                print("    n=%d→%d: |e_{n+1}|/|e_n| = %.10f  (subdominant target: ~0.067)" % (na, nb, r))

