def A_p27(n): return _sage_const_1024  * (_sage_const_2 *n+_sage_const_5 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 )
def B_p27(n): return _sage_const_128  * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_104060 *n**_sage_const_6  + _sage_const_1745370 *n**_sage_const_5  + _sage_const_12145238 *n**_sage_const_4  + _sage_const_44886481 *n**_sage_const_3  + _sage_const_92943995 *n**_sage_const_2  + _sage_const_102256019 *n + _sage_const_46709052 )
def C_p27(n): return _sage_const_16  * (n+_sage_const_3 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_3784 *n**_sage_const_5  + _sage_const_57792 *n**_sage_const_4  + _sage_const_351019 *n**_sage_const_3  + _sage_const_1059230 *n**_sage_const_2  + _sage_const_1587211 *n + _sage_const_944620 )
def D_p27(n): return (n+_sage_const_3 )**_sage_const_4  * (n+_sage_const_4 )**_sage_const_6  * (_sage_const_946 *n**_sage_const_2  + _sage_const_4515 *n + _sage_const_5399 )

for step_name, n1_fn in [("balanced", lambda n: (n+_sage_const_1 )//_sage_const_2 )]:
    print("\n--- %s ---" % step_name)
    vals = []
    for n in range(_sage_const_2 , min(max_n + _sage_const_1 , _sage_const_12 )):
        n1 = int(n1_fn(n))
        n2 = int(n) - n1
        if n2 < _sage_const_1  or n1 < _sage_const_1 :
            continue
        try:
            c, Qn1 = compute_mop(n, n1, n2)
            vals.append((n, Qn1))
        except:
            pass

    for i in range(_sage_const_3 , len(vals)):
        n_curr = vals[i][_sage_const_0 ]
        if vals[i-_sage_const_1 ][_sage_const_0 ] != n_curr-_sage_const_1  or vals[i-_sage_const_2 ][_sage_const_0 ] != n_curr-_sage_const_2  or vals[i-_sage_const_3 ][_sage_const_0 ] != n_curr-_sage_const_3 :
            continue
        u3 = vals[i][_sage_const_1 ]
        u2 = vals[i-_sage_const_1 ][_sage_const_1 ]
        u1 = vals[i-_sage_const_2 ][_sage_const_1 ]
        u0 = vals[i-_sage_const_3 ][_sage_const_1 ]
        nn = n_curr - _sage_const_3   # shift so u0 = Q_{nn}, ..., u3 = Q_{nn+3}
        pred = (mpmath.mpf(B_p27(nn+_sage_const_2 ))/A_p27(nn+_sage_const_2 ) * u2
                - mpmath.mpf(C_p27(nn+_sage_const_1 ))/A_p27(nn+_sage_const_1 ) * u1
                + mpmath.mpf(D_p27(nn))/A_p27(nn) * u0)
        res = u3 - pred
        rel = float(abs(res / u3)) if abs(u3) > _sage_const_1en100  else float(abs(res))
